Python<pre><code>backend = CompositeBackend(
    default=LocalBackend(root_dir="/home/user/my-app"),  # Persistent real files
    routes={
        "/scratch/": StateBackend(),  # Ephemeral in-memory space
    },
)

# Agent reads and writes real project files via LocalBackend
# Agent uses /scratch/ for intermediate or throwaway data
</code></pre>

Python<pre><code>from pydantic_ai_backends import CompositeBackend, LocalBackend, DockerSandbox

backend = CompositeBackend(
    default=LocalBackend(root_dir="/home/user/project"),
    routes={
        "/sandbox/": DockerSandbox(runtime="python-datascience"),
    },
)

# Read/write real project files by default
# Run untrusted code safely inside /sandbox/
</code></pre>

Python<pre><code>backend = CompositeBackend(
    default=StateBackend(),
    routes={
        "/plans/": StateBackend(),
        "/output/": StateBackend(),
    },
)

# Logically separate namespaces within a fully in-memory backend
# Useful for testing or agents that need internal partitioning
</code></pre>

Python<pre><code>from pydantic_ai_backends import DaytonaSandbox

# Missing API key
try:
    sandbox = DaytonaSandbox()  # No key in env either
except ValueError as e:
    print(e)  # "Daytona API key is required..."

# Sandbox startup timeout
try:
    sandbox = DaytonaSandbox(api_key="dtna_...", startup_timeout=5)
except RuntimeError as e:
    print(e)  # "Daytona sandbox failed to start within 5 seconds"
</code></pre>

